mapper.select:
SELECT count(1) count, min(duar.id) min_id, max(duar.id) max_id
FROM dwd_user_ad_record duar
WHERE duar.dates = #{dates}

SELECT *
FROM dwd_user_ad_record duar
WHERE duar.dates = #{dates}
  and duar.id >= #{startId}
  and duar.id
 <
      #{endId}

SELECT *
FROM dwd_user_ad_record duar
         INNER JOIN dim_user_info dui
                    on (duar.user_id = dui.user_id and duar.dates = dui.dates)
WHERE duar.dates = #{dates}
  and duar.id >= #{startId}
  and duar.id
 <
      #{endId}

SELECT duar.*, IFNULL(dus.network, 'Unknown') user_source
FROM dwd_user_ad_record duar
         left join dim_user_source dus on (dus.user_id = duar.user_id)
WHERE duar.dates = #{dates}
  and duar.id >= #{startId}
  and duar.id
 <
      #{endId}

SELECT duar.*, IFNULL(dus.network, 'Unknown') user_source
FROM dwd_user_ad_record duar
         INNER JOIN dim_user_info dui
                    on (duar.user_id = dui.user_id and duar.dates = dui.dates)
         left join dim_user_source dus on (dus.user_id = duar.user_id)
WHERE duar.dates = #{dates}
  and duar.id >= #{startId}
  and duar.id
 <
      #{endId}
